package be.winnetrie.mod.simpleserverutilities.network; import be.winnetrie.mod.simpleserverutilities.SimpleServerUtilities;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record AchievementEditorRequestPayload(String achievementId,long requestId) implements CustomPacketPayload{public static final Type<AchievementEditorRequestPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(SimpleServerUtilities.MODID,"achievement_editor_request"));public static final StreamCodec<RegistryFriendlyByteBuf,AchievementEditorRequestPayload> STREAM_CODEC=StreamCodec.of(AchievementEditorRequestPayload::encode,AchievementEditorRequestPayload::decode);public AchievementEditorRequestPayload{achievementId=PayloadBounds.string(achievementId,64);requestId=Math.max(0L,requestId);}private static void encode(RegistryFriendlyByteBuf b,AchievementEditorRequestPayload p){b.writeUtf(p.achievementId,64);b.writeVarLong(p.requestId);}private static AchievementEditorRequestPayload decode(RegistryFriendlyByteBuf b){return new AchievementEditorRequestPayload(b.readUtf(64),b.readVarLong());}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}
